&lt;li style=&quot;margin-top: 0in; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; color: black; font-size: 12pt;&quot;&gt;Ability to handle cleaning chemicals safely and follow proper guidelines.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0in; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; color: black; font-size: 12pt;&quot;&gt;Ability to work nights, weekends, and holidays based on business needs.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0in; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; color: black; font-size: 12pt;&quot;&gt;Willingness to assist with food prep work when needed.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
