&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Excellent oral and written communication and organizational skills.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233118&amp;quot;:true,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
